def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=dim)
    T = 1e3
    alpha = 0.99
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        y = x + 0.01 * rng.normal(size=dim)
        y = np.clip(y, lb, ub)

        f = func(y)

        if f < best_f:
            best_f = f
            best_x = y.copy()

        delta = f - best_f

        if delta <= 0 or np.random.rand() * T / (T + _ + 1) < np.exp(-delta / T):
            x = y

        else:
            if rng.rand() < 0.5:
                pass
            else:
                x = np.clip(x + 0.01 * rng.normal(size=dim), lb, ub)

        T *= alpha

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.maximum(np.minimum(x, ub), lb)

    x = np.zeros(dim)
    temperature = 1.0
    best_x = x.copy()
    best_val = func(x)

    for _ in range(budget):
        for i in range(dim):
            sigma = rng.uniform(0, 1) * (ub - lb)**2 / budget
            noise = np.random.normal(loc=0, scale=sigma, size=(dim,))
            new_x = clip(best_x + temperature * noise)

            if func(new_x) < best_val:
                best_x = new_x.copy()
                best_val = func(new_x)

        temperature *= 1 - rng.uniform(0, 1)**2

    return best_x

